pragma solidity 0.8.17;

library SafeMath {
function sub(uint256 a, uint256 b) internal pure returns (uint256) {
assert(b <= a);
return a - b;
}

function add(uint256 a, uint256 b) internal pure returns (uint256) {
uint256 c = a + b;
assert(c >= a);
return c;
}
}

contract WXETA {
using SafeMath for uint256;
bytes32 internal constant WXETANAMESPACE = keccak256('wxeta.facet');

struct WXETASTORAGE {
string name;
string symbol;
uint8 decimals;

address owner;
bool initialized;
uint256 _maxSupply;
uint256 _totalSupply;

mapping(address => bool) authorized;
mapping(address => uint256) balances;
mapping(address => mapping (address => uint256)) allowed;
}

function getWXETAStorage() internal pure returns(WXETASTORAGE storage s) {
bytes32 position = WXETANAMESPACE;
assembly {
s.slot := position
}
}

event Transfer(address indexed from, address indexed to, uint tokens);
event Approval(address indexed tokenOwner, address indexed spender, uint tokens);

modifier onlyOwner() {
require(msg.sender == getWXETAStorage().owner, "WXETA: not owner");
_;
}

modifier onlyAuthorized() {
require(getWXETAStorage().authorized[msg.sender], "WXETA: not authorized");
_;
}

function initialize(uint256 max) public {
WXETASTORAGE storage s = getWXETAStorage();
require(!s.initialized, "WXETA: already initialized");
s._maxSupply = max;
s.owner = msg.sender;
s.authorized[msg.sender] = true;
s.name = "Wrapped Xeta";
s.symbol = "WXETA";
s.decimals = 18;
}

function totalSupply() public view returns (uint256) {
return getWXETAStorage()._totalSupply;
}

function maxSupply() public view returns (uint256) {
return getWXETAStorage()._maxSupply;
}

function balanceOf(address tokenOwner) public view returns (uint) {
return getWXETAStorage().balances[tokenOwner];
}

function mint(address receiver, uint256 amount) public onlyAuthorized() returns(bool) {
WXETASTORAGE storage s = getWXETAStorage();
require(s._totalSupply + amount <= s._maxSupply, "Mint exceeds maximum supply");

s._totalSupply = totalSupply().add(amount);
s.balances[receiver] = s.balances[receiver].add(amount);
emit Transfer(address(this), receiver, amount);
return true;
}

function burn(address from, uint256 amount) public onlyAuthorized() returns(bool) {
WXETASTORAGE storage s = getWXETAStorage();
require(s.balances[from] >= amount, "Insufficient balance to burn");

s._totalSupply = s._totalSupply.sub(amount);
s.balances[from] = s.balances[from].sub(amount);
emit Transfer(from, address(0), amount);
return true;
}

function approve(address delegate, uint numTokens) public returns (bool) {
WXETASTORAGE storage s = getWXETAStorage();
s.allowed[msg.sender][delegate] = numTokens;
emit Approval(msg.sender, delegate, numTokens);
return true;
}

function allowance(address user, address delegate) public view returns (uint) {
return getWXETAStorage().allowed[user][delegate];
}

function transfer(address receiver, uint numTokens) public returns (bool) {
WXETASTORAGE storage s = getWXETAStorage();
require(numTokens <= s.balances[msg.sender]);
require(receiver != address(0), "WXETA: Cannot transfer to the zero address");

s.balances[msg.sender] = s.balances[msg.sender].sub(numTokens);
s.balances[receiver] = s.balances[receiver].add(numTokens);
emit Transfer(msg.sender, receiver, numTokens);
return true;
}

function transferFrom(address user, address receiver, uint numTokens) public returns (bool) {
WXETASTORAGE storage s = getWXETAStorage();
require(numTokens <= s.balances[user]);
require(numTokens <= s.allowed[user][msg.sender]);
require(receiver != address(0), "WXETA: Cannot transfer to the zero address");

s.balances[user] = s.balances[user].sub(numTokens);
s.allowed[user][msg.sender] = s.allowed[user][msg.sender].sub(numTokens);
s.balances[receiver] = s.balances[receiver].add(numTokens);
emit Transfer(user, receiver, numTokens);
return true;
}

function setAuthorized(address _address, bool _status) public onlyOwner() {
getWXETAStorage().authorized[_address] = _status;
}

function authorized(address _add) external view returns(bool) {
return getWXETAStorage().authorized[_add];
}

function owner() external view returns(address) {
return getWXETAStorage().owner;
}

function name() external view returns(string memory) {
return getWXETAStorage().name;
}

function symbol() external view returns(string memory) {
return getWXETAStorage().symbol;
}

function decimals() external view returns(uint256) {
return getWXETAStorage().decimals;
}
}
```

## Fuzzing task — strategy: reentrancy_probe

**Objective:** Build a transaction sequence in which the attacker-controlled address (attacker_address) ends up with more total value (native coin + tokens) than it spent — i.e. extract funds from the target or break a value invariant in the attacker's favor. Use at most 12 calls per sequence.

**Goal:** Detect reentrancy vulnerabilities (CEI pattern violations).

**Technique:**
Scan the ABI for functions that SEND ETH OUT to msg.sender (typical name patterns: withdraw*, claim*, redeem*, unstake*, cashOut*, emergencyWithdraw*, *ETH, *Funds, harvest*, payout* — but use whatever names this ABI actually has). Configure attacker reentry on one of those functions, fund the contract via a PAYABLE function (typical names: deposit*, stake*, mint*, fund*, buy*, contribute*), then trigger the ETH-sending function so the attacker's receive() callback re-enters. DO NOT default to the names in the example below — they are placeholders.

**Value hints:** Use "0xde0b6b3a7640000" (1 ETH) for payable calls. Use "0x0" for non-payable.

**Valid callers:** "attacker_address"
Use only these alias name(s) in the `caller_name` (msg.sender) slot — there is a
single attacker identity, so every call already runs as the attacker. Never use
"deployer_address" or a raw hex address as a caller. (Address-TYPED ARGUMENTS are
separate: see "Special argument values" below for the aliases those slots accept —
you are NOT restricted to the caller alias there.)
**Strategy notes:** Use "atk.setReentrantCall" as the FIRST call to arm the attacker's re-entry callback: ["atk.setReentrantCall", {"reentrant_func": "fnName", "reentrant_args": ["0x..."], "max_count": 3}, "0x0", "attacker_address"]. The attacker re-enters whenever the target calls BACK into it — either by sending it ETH (receive) or by invoking an unknown selector on it (fallback: e.g. an ERC777/hook/migration callback) — so this covers callback-driven reentrancy too, not just native-ETH transfers. reentrant_func is the function re-called during that callback: a BARE function name from THIS target's ABI (no parentheses, no type list; re-entry always hits the main contract, never an external var). reentrant_args matches that function's input types (use [] if no args). max_count is the re-entry depth (1-5). There is ONE attacker identity: route the arm, the funding/setup AND the final trigger call all through attacker_address (the unified attacker contract) so the callback fires with the attacker as msg.sender.
**Special argument values:**
- address-typed args accept `target_address`, `attacker_address`, or a raw 0x literal.
- `"max"` → uint256 max; `"now"` → block.timestamp.
- `"$ret<idx>"` → feed the RETURN VALUE of the call at 0-based index <idx> in this sequence into this argument (that call must return exactly one value).

**Argument encoding (match each value to its ABI parameter type):**
- uint* / bytesN / bytes → hex string, e.g. "0x1f" (minimal, not zero-padded)
- int* (signed) → decimal string, e.g. "-5"
- bool → true or false (JSON literal, unquoted)
- address → an alias name (see callers/aliases above) or a 40-hex-digit 0x literal
- arrays → JSON list, e.g. [] or ["0x1", "0x2"]; tuples/structs → JSON list of their fields
- empty bytes / empty signature / empty proof → "0x" or []

**Output format:**
Return a JSON array of 1 fuzz input object(s):
[
  {
    "calls": [["functionName", [arg1, arg2], "0x<wei_hex>", "caller_name"], ...],
    "description": "brief description"
  }
]
JSON only — no markdown, no explanation.

**Example sequence:**
```json
Structural pattern (replace UPPERCASE placeholders with real ABI function names):
  [["atk.setReentrantCall", {"reentrant_func": "<ETH_SENDER_FROM_ABI>", "reentrant_args": [], "max_count": 4}, "0x0", "attacker_address"],
   ["<PAYABLE_FUNC_FROM_ABI>", [], "0xde0b6b3a7640000", "attacker_address"],
   ["<PAYABLE_FUNC_FROM_ABI>", [], "0xde0b6b3a7640000", "attacker_address"],
   ["<ETH_SENDER_FROM_ABI>", [], "0x0", "attacker_address"]]
```

